import pygame

def handle_event(type_id, key, highlight):
    if type_id == pygame.QUIT:
        return False, highlight
    if type_id == pygame.KEYDOWN:
        if key == pygame.K_ESCAPE:
            return False, highlight
        if key == pygame.K_SPACE:
            return True, not highlight
    return True, highlight

def court(width, height, highlight=False):
    canvas = pygame.Surface((width, height))
    canvas.fill((16, 23, 39))
    pygame.draw.rect(canvas, (235, 240, 250), (20, height // 2 - 30, 10, 60))
    pygame.draw.rect(canvas, (235, 240, 250), (width - 30, height // 2 - 30, 10, 60))
    colour = (255, 170, 40) if highlight else (235, 240, 250)
    pygame.draw.rect(canvas, colour, (width // 2 - 3, height // 2 - 3, 6, 6))
    return canvas
